import json,hashlib
from pathlib import Path
p=Path('docs/implementation/PHASE_03_FRESH_WINDOW_PILOT_EVIDENCE.json');e=json.loads(p.read_text());w=Path(e['roots']['worker'])
reviews=[]
for i in range(8):
 entry=json.loads((w/f'window_{i:03}.json').read_text());v={'market_id':entry['item']['member']['market_id'],'question':entry['item']['identity']['question'],'missing_reason':entry['missing_reason'],'sources':[]}
 for rp in sorted((w/f'fs2_capture_screen_{i:03}').glob('*/receipt.json')):
  r=json.loads(rp.read_text());raw=rp.parent/'raw.bin';b=raw.read_bytes();j=json.loads(b)
  if isinstance(j,list):j=j[0]
  rec={'source_id':r['source_id'],'raw_path':str(raw),'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b),'receipt_path':str(rp),'receipt_sha256':hashlib.sha256(rp.read_bytes()).hexdigest()}
  if r['source_id']=='gamma.market':rec['fields']={k:j.get(k) for k in ['active','closed','archived','acceptingOrders','enableOrderBook','endDate','liquidity','volume']}
  if r['source_id']=='clob.book':rec['fields']={'bid_levels':len(j.get('bids',[])),'ask_levels':len(j.get('asks',[])),'raw_timestamp':j.get('timestamp')}
  v['sources'].append(rec)
 reviews.append(v)
e['availability_review']=reviews
e['family_eligibility_review']={'external':'None of the eight questions matches the measured KNYC station quantity. No selected external rule/source/time mapping exists. Unavailable remains correct.','related':'France and Spain EURO 2028 winner questions suggest a candidate relation, but titles alone do not prove the complete rule-aware outcome set or economic grouping. No causal related-price feature is bound; unavailable remains correct.','flow_depth_persistence':'Raw trades and receipt-window diagnostics do not prove fill completeness, pre-trade ordering, execution-adjusted deltas or native continuity. F01/F02/F10/F27 stay unavailable.','v1':'Two-snapshot history is not the rolling return z-score or seven-component v1 input vector. No v1 output is reconstructed from these pilot inputs.'}
e['conclusion']='Failed frozen six-of-eight origin/history gates; five timely observed origins and five valid targets, one matched pair. Three one-sided HTTP200 books despite active/nonclosed/accepting Gamma flags. No retrospective filtering, resampling or acceptance.'
p.write_text(json.dumps(e,indent=2,sort_keys=True)+'\n')
print('bytes',p.stat().st_size)
